func initCloudRanges() {
	cloudRanges = make([]cloudIPRange, len(cloudRangeSpecs))
	for i, s := range cloudRangeSpecs {
		cloudRanges[i] = mustParseCIDR(s.cidr, s.provider)
	}
}

// IPRangeProvider returns the cloud provider for an IP address.
// Returns ProviderUnknown if not a known cloud provider IP.
func IPRangeProvider(addr string) CloudProvider {
	cloudOnce.Do(initCloudRanges)

	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		host = addr
	}

	ip := net.ParseIP(host)
	if ip == nil {
		return ProviderUnknown
	}

	for _, r := range cloudRanges {
		if r.network.Contains(ip) {
			return r.provider
		}
	}

	return ProviderUnknown
}

// IsCloudProvider returns true if the IP belongs to any known cloud provider.
func IsCloudProvider(addr string) bool {
	return IPRangeProvider(addr) != ProviderUnknown
}
